import{_ as p,a0 as l,w as o,s as u,ao as h,I as n,x as i,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 TimeShift 備份和還原 Ubuntu Linux | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 TimeShift 備份和還原 Ubuntu Linux | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 TimeShift 備份和還原 Ubuntu Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 TimeShift 備份和還原 Ubuntu Linux | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191120 How to Use TimeShift to Backup and Restore Ubuntu Linux","title":"如何使用 TimeShift 備份和還原 Ubuntu Linux","tag":"201911","desc":""},"relativePath":"201911/20191120 How to Use TimeShift to Backup and Restore Ubuntu Linux.md","filePath":"[post].md"}'),r={name:"201911/20191120 How to Use TimeShift to Backup and Restore Ubuntu Linux.md"};function d(m,t,c,b,g,f){const e=l("Link");return o(),u("div",null,[t[15]||(t[15]=h(`<h1 id="如何使用-timeshift-備份和還原-ubuntu-linux" tabindex="-1">如何使用 TimeShift 備份和還原 Ubuntu Linux <a class="header-anchor" href="#如何使用-timeshift-備份和還原-ubuntu-linux" aria-label="Permalink to “如何使用 TimeShift 備份和還原 Ubuntu Linux”">​</a></h1><p>你是否曾經想過如何備份和還原 Ubuntu 或 Debian 系統？Timeshift 是一款自由開源工具，可讓你創建文件系統的增量快照。你可以使用 RSYNC 或 BTRFS 兩種方式創建快照。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201911/27/235959fejmb080e7z0jnu0.jpg" alt=""></p><p>讓我們深入研究並安裝 Timeshift。在本教程，我們將安裝在 Ubuntu 18.04 LTS 系統上。</p><h3 id="在-ubuntu-debian-linux-上安裝-timeshift" tabindex="-1">在 Ubuntu / Debian Linux 上安裝 TimeShift <a class="header-anchor" href="#在-ubuntu-debian-linux-上安裝-timeshift" aria-label="Permalink to “在 Ubuntu / Debian Linux 上安裝 TimeShift”">​</a></h3><p>TimeShift 尚未正式託管在 Ubuntu 和 Debian 倉庫中。考慮到這一點，我們將運行以下命令來添加 PPA：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># add-apt-repository -y ppa:teejee2008/ppa</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Add-timeshift-repository.png" alt="Add timeshift repository"></p><p>接下來，使用以下命令更新系統軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt update</span></span></code></pre></div><p>成功更新系統後，使用以下 <code>apt</code> 命令安裝 Timeshift：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install timeshift</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/apt-install-timeshift.png" alt="apt install timeshift"></p><h3 id="準備備份存儲設備" tabindex="-1">準備備份存儲設備 <a class="header-anchor" href="#準備備份存儲設備" aria-label="Permalink to “準備備份存儲設備”">​</a></h3><p>最佳實踐要求我們將系統快照保存在系統硬盤之外的單獨的存儲捲上。對於本指南，我們將使用 16GB 閃存作為第二個驅動器，並在該驅動器上保存快照。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk | grep sdb</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/lsblk-sdb-ubuntu.png" alt="lsblk sdb ubuntu"></p><p>為了將閃存用作快照的備份位置，我們需要在設備上創建一個分區表。運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># parted /dev/sdb  mklabel gpt</span></span>
<span class="line"><span># parted /dev/sdb  mkpart primary 0% 100%</span></span>
<span class="line"><span># mkfs.ext4  /dev/sdb1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/create-partition-table-on-drive-ubuntu.jpg" alt="create partition table on drive ubuntu"></p><p>在 USB 閃存上創建分區表後，我們可以開始創建文件系統的快照！</p><h3 id="使用-timeshift-創建快照" tabindex="-1">使用 Timeshift 創建快照 <a class="header-anchor" href="#使用-timeshift-創建快照" aria-label="Permalink to “使用 Timeshift 創建快照”">​</a></h3><p>要啓動 Timeshift，使用應用程序菜單搜索 “Timeshift”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Access-Timeshift-Ubuntu.jpg" alt="Access timeshift"></p><p>單擊 Timeshift 圖標，系統將提示你輸入管理員密碼。提供密碼，然後單擊驗證。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Authentication-required-ubuntu.jpg" alt="Authentication required"></p><p>接下來，選擇你喜歡的快照類型。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Select-Rsync-option-timeshift.jpg" alt="Select rsync option"></p><p>點擊 “Next”。選擇快照的目標驅動器。在這裏，我的位置是標記為 <code>/dev/sdb</code> 的外部 USB 驅動器。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Select-snapshot-location.png" alt="Select snapshot location"></p><p>接下來，定義快照級別。級別是指創建快照的時間間隔。你可以選擇每月、每週、每天或每小時的快照級別。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Select-snapshot-levels-Timeshift.jpg" alt="Select snapshot levels"></p><p>點擊 “Finish”。</p><p>在下一個窗口中，單擊 “Create” 按鈕開始創建快照。此後，系統將開始創建快照。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Create-snapshot-timeshift.jpg" alt="Create snapshot"></p><p>最後，你的快照將顯示如下：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Snapshot-created-TimeShift.jpg" alt="Snapshot created"></p><h3 id="從快照還原-ubuntu-debian" tabindex="-1">從快照還原 Ubuntu / Debian <a class="header-anchor" href="#從快照還原-ubuntu-debian" aria-label="Permalink to “從快照還原 Ubuntu / Debian”">​</a></h3><p>創建系統快照後，現在讓我們看看如何從同一快照還原系統。在同一個 Timeshift 中，單擊快照，然後單擊 “Restore” 按鈕，如圖所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Restore-snapshot-timeshift.jpg" alt="Restore snapshot"></p><p>接下來，將提示你選擇目標設備。保留默認選擇，然後點擊 “Next”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Select-target-device-timeshift.jpg" alt="Select target device"></p><p>恢復過程開始之前，Timeshift 將會試運行。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Comparing-files-Dry-Run-timeshift.jpg" alt="Comparing files dry run"></p><p>在下一個窗口中，點擊 “Next” 按鈕確認顯示的操作。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Confirm-actions-timeshift.jpg" alt="Confirm actions"></p><p>如圖所示，你會看到警告和免責聲明。點擊 “Next” 初始化恢復過程。</p><p>此後，將開始還原過程，最後，系統之後將重新啓動到快照定義的早期版本。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Restoring-snapshot-timeshift.png" alt="Restoring snapshot"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如你所見，使用 TimeShift 從快照還原系統非常容易。在備份系統文件時，它非常方便，並允許你在系統故障時進行恢復。因此，不要害怕修改系統或弄亂系統。TimeShift 使你能夠返回到一切運行平穩的時間點。</p><hr>`,52)),n("p",null,[t[1]||(t[1]=i("via: ",-1)),s(e,{href:"https://www.linuxtechi.com/timeshift-backup-restore-ubuntu-linux/"},{default:a(()=>[...t[0]||(t[0]=[i("https://www.linuxtechi.com/timeshift-backup-restore-ubuntu-linux/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=i("作者：",-1)),s(e,{href:"https://www.linuxtechi.com/author/james/"},{default:a(()=>[...t[2]||(t[2]=[i("James Kiarie",-1)])]),_:1}),t[7]||(t[7]=i(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[3]||(t[3]=[i("lujun9972",-1)])]),_:1}),t[8]||(t[8]=i(" 譯者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[4]||(t[4]=[i("geekpi",-1)])]),_:1}),t[9]||(t[9]=i(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[5]||(t[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[10]||(t[10]=[i("LCTT",-1)])]),_:1}),t[13]||(t[13]=i(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:a(()=>[...t[11]||(t[11]=[i("Linux中國",-1)])]),_:1}),t[14]||(t[14]=i(" 榮譽推出",-1))])])}const T=p(r,[["render",d]]);export{x as __pageData,T as default};
